            var original=FindAssistCandidate(_assistTargetAcd);
            CancelAssistDoor();ReleaseAssistAttack();CancelTarget();RememberAssistHazardReturn(original);
            _mainKey=_assistMainKey;_combinationDisplayKey=_mainKey;
