        private const int AssistDoorProbeCount=6;
        private int _assistDoorInputWaitAt=int.MinValue,_assistDoorInputWaitTotal;
        private bool AssistDoorNeedsPathRecovery(IActor door)
        {
            AssistDoorFailure failure;
