        private bool AssistSkeletonFireEscapeDue()
        {
            if(!AvoidSkeletonMageFire || !_assistFirePoolAvoiding || !_assistPositionReadable || AssistShieldPylonActive())return false;
            var me=Hud.Game.Me.FloorCoordinate;
