                if(IsAssistSkeletonFireField(field) && !field.IsDisabled && AssistSameHeight(me,field.FloorCoordinate)
                    && me.XYDistanceTo(field.FloorCoordinate)<=AssistSkeletonFirePoolClearance)return true;
